local a=peripheral.find("modem")if not a then print("no modem found")return end;local b=42;a.open(b)local c=("x"):rep(256)local function d(e)local f=os.epoch("utc")for g=1,e do a.transmit(b,b,c)end;return os.epoch("utc")-f end;for g,e in ipairs({1,5,10,20})do local h=d(e)print(("%3d transmit(s): %d ms  (%.1f ms/call)"):format(e,h,h/e))end;print("Compare to setPower ~50ms/call. If << 50ms, telemetry is cheap.")